test('AT-F33 ローカル補助: お気に入り・最近開いた削除済み場面を説明付き履歴へ移し、coldと履歴取消で同じ本文ID・表示設定を保つ', async ({ page }, info) => {
  const p = createProject('AT-F33 削除済み再開リンク');
  const sceneBody = textToRichText('再開する同じ場面🌸。削除と復元でも段落IDを保つ。');
  const scene = createEntity(p.projectId, 'scene', '削除後に再開する場面', { body: sceneBody });
  const other = createEntity(p.projectId, 'scene', '先に登録した場面', { body: textToRichText('もう一件の順序を保持する。') });
  const a = createEntity(p.projectId, 'character', '再開配置A'), b = createEntity(p.projectId, 'character', '再開配置B');
  p.entities.push(scene, other, a, b); p.entities.forEach(entity => { entity.status = 'confirmed'; });
  p.relations.push({ id: newId(), projectId: p.projectId, revision: '0', fromId: a.id, toId: b.id, relationType: 'trust', direction: 'forward', validity: emptyValidity(), evidenceIds: [], status: 'confirmed', visibility: 'private' });
  const bytes = await exportScenario(p);
  await attachGiven(info, 'AT-F33-local-recovery', bytes, { localScopeOnly: true, sceneId: scene.id, sourceBlockIds: sceneBody.map(block => block.id), secondSceneId: other.id, graphIds: [a.id, b.id], actualSmartphoneAndOtherDevice: 'not_run' });
  await page.setViewportSize({ width: 1440, height: 1000 }); await seed(page, bytes);
  const originalNative = await authorFingerprint(page);
  await graph(page);
  const node = page.getByRole('button', { name: `${a.name}を選択。矢印キーで配置を移動、Enterで詳細`, exact: true });
  await node.click(); await page.getByLabel('選択した項目の横位置', { exact: true }).fill('400');
  await page.getByLabel('選択した項目の縦位置', { exact: true }).fill('240');
  await page.getByRole('button', { name: '座標を適用', exact: true }).click();
  const zoom = page.getByLabel('関係図の拡大率', { exact: true });
  await zoom.press('End'); await zoom.press('ArrowLeft'); await zoom.press('ArrowLeft');
  await expect(node.locator('text')).toHaveAttribute('x', '400');
  await page.setViewportSize({ width: 390, height: 844 });
  await expect(page.getByLabel('関係図の拡大率', { exact: true })).toHaveValue('1');
  await node.click(); await page.getByLabel('選択した項目の横位置', { exact: true }).fill('220');
  await page.getByLabel('選択した項目の縦位置', { exact: true }).fill('160');
  await page.getByRole('button', { name: '座標を適用', exact: true }).click();
  await page.setViewportSize({ width: 1440, height: 1000 });
  await expect(node.locator('text')).toHaveAttribute('x', '400');
  await expect(page.getByLabel('関係図の拡大率', { exact: true })).toHaveValue('1.5');
  expect(await authorFingerprint(page)).toBe(originalNative);
  for (const target of [other, scene]) {
    await openEntity(page, 'scene', target.name); const panel = await marks(page);
    await panel.getByRole('button', { name: 'お気に入りに登録', exact: true }).click();
  }
  const savedMarks = await readMarks(page, p.projectId);
  expect(savedMarks).toEqual({ favoriteIds: [other.id, scene.id], recentIds: [scene.id, other.id] });
  await page.locator('.editor-footer').getByRole('button', { name: 'アーカイブ', exact: true }).click();
  await page.getByRole('dialog', { name: 'アーカイブの確認', exact: true }).getByRole('button', { name: 'アーカイブする', exact: true }).click();
  await expect(page.getByRole('dialog', { name: 'アーカイブの確認', exact: true })).toHaveCount(0);
  await page.reload(); const panel = await marks(page);
  expect(await readMarks(page, p.projectId)).toEqual(savedMarks);
  const afterArchiveNative = await authorFingerprint(page);
  for (const title of ['お気に入り', '最近開いた情報']) {
    const section = panel.locator('section').filter({ has: page.getByRole('heading', { name: title, exact: true }) });
    const stale = section.locator('.navigation-mark-stale');
    await expect(stale).toContainText(scene.name); await expect(stale).toContainText('アーカイブ済み');
    await expect(stale).toContainText('変更履歴で元の情報と復元方法を確認できます');
    await stale.getByRole('button', { name: `${scene.name} の履歴・復元案内を開く`, exact: true }).click();
    await expect(page.getByRole('tab', { name: '変更履歴', exact: true })).toHaveAttribute('aria-selected', 'true');
    await expect(page.locator('.history-page')).toBeVisible();
    await expect(page.locator('.history-page')).toContainText('アーカイブ済みの情報');
    await expect(page.locator('.detail-panel')).toHaveCount(0);
    expect(await readMarks(page, p.projectId)).toEqual(savedMarks);
    expect(await authorFingerprint(page)).toBe(afterArchiveNative);
  }
  await page.locator('.history-page').getByRole('button', { name: 'この変更を取り消す', exact: true }).click();
  await expect(page.locator('.history-page').getByRole('status').filter({ hasText: '復元' })).toBeVisible();
  await page.reload(); const restoredPanel = await marks(page);
  await expect(restoredPanel.locator('.navigation-mark-stale')).toHaveCount(0);
  expect(await readMarks(page, p.projectId)).toEqual(savedMarks);
  const favorite = restoredPanel.locator('section').filter({ has: page.getByRole('heading', { name: 'お気に入り', exact: true }) });
  await favorite.getByRole('button', { name: `${scene.name} 場面`, exact: true }).click();
  await page.locator('.detail-panel').getByRole('tab', { name: '本文', exact: true }).click();
  await expect(page.locator('.detail-panel').getByRole('textbox', { name: '本文', exact: true })).toHaveValue(sceneBody[0].text);
  const saved = await backup(page), retained = saved.project.entities.find(entity => entity.id === scene.id);
  expect(retained?.deletedAt).toBeFalsy(); expect(retained?.data).toEqual(scene.data);
  expect(saved.project.entities.map(entity => entity.id).sort()).toEqual(p.entities.map(entity => entity.id).sort());
  expect(saved.project.relations).toEqual(p.relations);
  expect(saved.project.history.filter(command => command.compensatesOperationId)).toHaveLength(1);
  await graph(page); await expect(node.locator('text')).toHaveAttribute('x', '400');
  await expect(page.getByLabel('関係図の拡大率', { exact: true })).toHaveValue('1.5');
  await page.setViewportSize({ width: 390, height: 844 });
  await expect(node.locator('text')).toHaveAttribute('x', '220');
  await expect(page.getByLabel('関係図の拡大率', { exact: true })).toHaveValue('1');
  await attachObservation(info, 'AT-F33-local-recovery-observed', { sceneId: scene.id, sourceBlockIds: sceneBody.map(block => block.id), savedMarks, recoveryGuidanceFromBothLists: true, guidanceDoesNotRestoreOrChangeAuthorData: true, undoRestoredSameEntityAndBlockIds: true, sameBrowserDesktop: { x: 400, zoom: 1.5 }, sameBrowserPhoneClass: { x: 220, zoom: 1 }, physicalSmartphoneAndOtherDevice: 'not_run', revision: saved.project.revision });
});

test('AT-F03 同じ場面Sを恋愛・戦争の二つの筋から開き、一方で修正しても本文と参加関係を複製しない', async ({ page }, info) => {
  const p = createProject('AT-F03 二つの筋と同じ場面');
  const romance = createEntity(p.projectId, 'group', '恋愛の筋', { groupType: 'plot_thread' });
  const war = createEntity(p.projectId, 'group', '戦争の筋', { groupType: 'plot_thread' });
  const actor = createEntity(p.projectId, 'character', '場面に実際に参加する人物');
  const event = createEntity(p.projectId, 'event', '場面Sの実参加', { participants: [{ characterId: actor.id, role: 'actor' }], laneRole: 'participants' });
  const scene = createEntity(p.projectId, 'scene', '場面S', { body: textToRichText('二つの筋で共有する元の本文。'), threadIds: [], eventIds: [event.id] });
  p.entities.push(romance, war, actor, event, scene);
  p.entities.forEach(e => { e.status = 'confirmed'; });
  const bytes = await exportScenario(p);
  await attachGiven(info, 'AT-F03', bytes, { sceneId: scene.id, threadIds: scene.data.threadIds, realParticipants: event.data.participants });
  await seed(page, bytes);
  await openEntity(page, 'scene', scene.name);
  await page.locator('.detail-panel').getByRole('tab', { name: '詳細', exact: true }).click();
  const threads = page.locator('.detail-panel [data-field="threadIds"]');
  for (const id of [romance.id, war.id]) await threads.getByLabel('追加する対象', { exact: true }).selectOption(id);
  await saveEditor(page);
  await writing(page, '章・本文');
  const workspace = page.getByRole('region', { name: '物語の構成', exact: true });
  await workspace.getByLabel('物語の並べ方', { exact: true }).selectOption('thread');
  const romanceCard = workspace.locator(`[data-lane-id="${romance.id}"] [data-scene-id="${scene.id}"]`);
  const warCard = workspace.locator(`[data-lane-id="${war.id}"] [data-scene-id="${scene.id}"]`);
  await expect(romanceCard).toBeVisible(); await expect(warCard).toBeVisible();
  await romanceCard.locator('.story-scene-link').click();
  await page.locator('.detail-panel').getByRole('tab', { name: '本文', exact: true }).click();
  await page.locator('.detail-panel').getByRole('textbox', { name: '本文', exact: true }).fill('恋愛の筋のカードから修正した同じ本文。');
  await saveEditor(page);
  const editedBlockId = await page.locator('.detail-panel [data-field="body"] [data-block-id]').getAttribute('data-block-id');
  if (!editedBlockId) throw new Error('修正後の場面Sの実段落IDがありません');
  expect(editedBlockId).toMatch(ID_PATTERN);
  await page.getByRole('button', { name: '詳細を閉じる', exact: true }).click();
  await warCard.locator('.story-scene-link').click();
  await page.locator('.detail-panel').getByRole('tab', { name: '本文', exact: true }).click();
  await expect(page.locator('.detail-panel').getByRole('textbox', { name: '本文', exact: true })).toHaveValue('恋愛の筋のカードから修正した同じ本文。');
  await expect(page.locator('.detail-panel [data-field="body"] [data-block-id]')).toHaveAttribute('data-block-id', editedBlockId);
  await page.getByRole('button', { name: '詳細を閉じる', exact: true }).click();
  await romanceCard.getByRole('button', { name: 'この筋から外す', exact: true }).click();
  await expect(romanceCard).toHaveCount(0); await expect(warCard).toBeVisible();
  await page.reload();
  const saved = await backup(page);
  expect(saved.project.entities.filter(e => e.id === scene.id)).toHaveLength(1);
  expect(saved.project.entities.filter(e => e.kind === 'scene')).toHaveLength(1);
  const savedScene = saved.project.entities.find(e => e.id === scene.id);
  if (!savedScene || savedScene.kind !== 'scene') throw new Error('保存後の同じ場面Sがありません');
  expect(savedScene).toMatchObject({ id: scene.id, projectId: p.projectId, name: scene.name, data: { threadIds: [war.id], eventIds: [event.id] } });
  expect(savedScene.data.body).toEqual([{ id: editedBlockId, kind: 'paragraph', text: '恋愛の筋のカードから修正した同じ本文。' }]);
  const editCommand = saved.project.history.find(command => command.targetIds.includes(scene.id)
    && command.before.entities.some(entity => entity.id === scene.id && entity.kind === 'scene' && JSON.stringify(entity.data.body) === JSON.stringify(scene.data.body))
    && command.after.entities.some(entity => entity.id === scene.id && entity.kind === 'scene' && JSON.stringify(entity.data.body) === JSON.stringify(savedScene.data.body)));
  if (!editCommand) throw new Error('場面Sの元本文と修正後の同じ本文を保持する履歴がありません');
  const originalScene = editCommand.before.entities.find(entity => entity.id === scene.id);
  if (!originalScene || originalScene.kind !== 'scene') throw new Error('場面Sの元本文を保持する変更前履歴がありません');
  expect(originalScene.data.body).toEqual(scene.data.body);
  expect(saved.project.entities.find(e => e.id === event.id)?.data).toEqual(event.data);
  await writing(page, '章・本文');
  await workspace.getByLabel('物語の並べ方', { exact: true }).selectOption('thread');
  await expect(romanceCard).toHaveCount(0); await expect(warCard).toBeVisible();
  await attachObservation(info, 'AT-F03-observed', { sceneId: scene.id, bodyBlockId: editedBlockId, originalBodyBlockId: scene.data.body[0].id, editHistoryOperationId: editCommand.operationId, remainingThreadIds: [war.id], participantIds: [actor.id], revision: saved.project.revision, bodyWasNotDuplicated: true });
});

test('AT-F04 鍵を探す場面Sの視点・目標・対立・結果・新情報を通常入力し、役割未入力の場面Tも保存できる', async ({ page }, info) => {
  const p = createProject('AT-F04 場面の理由と変化');
  const person = createEntity(p.projectId, 'character', '人物A');
  const scene = createEntity(p.projectId, 'scene', '鍵を探す場面S', { body: textToRichText('人物Aは塔の鍵を探す。') });
  const blank = createEntity(p.projectId, 'scene', '役割未入力の場面T');
  p.entities.push(person, scene, blank);
  const bytes = await exportScenario(p);
  await attachGiven(info, 'AT-F04', bytes, { personId: person.id, sceneId: scene.id, blankSceneId: blank.id, blankRoleFields: { povId: blank.data.povId, goals: blank.data.goals, conflicts: blank.data.conflicts, results: blank.data.results, newInformation: blank.data.newInformation } });
  await seed(page, bytes); await openEntity(page, 'scene', scene.name);
  const editor = page.locator('.detail-panel');
  await editor.getByRole('tab', { name: '詳細', exact: true }).click();
  await editor.getByLabel('視点人物', { exact: true }).selectOption(person.id);
  for (const [label, value] of [['目標', '人物Aが塔の鍵を見つける'], ['葛藤', '鍵を持つ鳥が警戒する'], ['変化・結果', '鍵は得たが鳥との約束を負う'], ['新しい情報', '門は夜にしか開かない']] as const) await editor.getByRole('textbox', { name: label, exact: true }).fill(value);
  await saveEditor(page);
  await openEntity(page, 'scene', blank.name);
  await saveEditor(page);
  await page.reload();
  const saved = await backup(page);
  const actual = saved.project.entities.find(e => e.id === scene.id);
  expect(actual?.kind).toBe('scene');
  if (!actual || actual.kind !== 'scene') throw new Error('場面Sが保存されていません');
  expect(actual.data.povId).toBe(person.id);
  for (const [key, value] of [['goals', '人物Aが塔の鍵を見つける'], ['conflicts', '鍵を持つ鳥が警戒する'], ['results', '鍵は得たが鳥との約束を負う'], ['newInformation', '門は夜にしか開かない']] as const) expect(actual.data[key]?.map(b => b.text).join('\n')).toBe(value);
  expect(actual.data.body).toEqual(scene.data.body);
  expect(saved.project.entities.find(e => e.id === blank.id)?.data).toEqual(blank.data);
  expect(saved.project.entities.some(e => e.kind === 'review')).toBe(false);
  await writing(page, '章・本文');
  const arc = page.getByRole('region', { name: '物語の構成', exact: true });
  await arc.getByLabel('物語の並べ方', { exact: true }).selectOption('character');
  const roles = arc.getByRole('region', { name: `${scene.name}の人物変化`, exact: true });
  for (const text of ['人物Aが塔の鍵を見つける', '鍵を持つ鳥が警戒する', '鍵は得たが鳥との約束を負う', '門は夜にしか開かない']) await expect(roles).toContainText(text);
  await openEntity(page, 'scene', blank.name);
  await editor.getByRole('tab', { name: '詳細', exact: true }).click();
  await expect(editor.getByLabel('視点人物', { exact: true })).toHaveValue('');
  for (const label of ['目標', '葛藤', '変化・結果', '新しい情報']) await expect(editor.getByRole('textbox', { name: label, exact: true })).toHaveValue('');
  await attachObservation(info, 'AT-F04-observed', { sceneId: scene.id, blankSceneId: blank.id, revision: saved.project.revision, authorRoleValues: { goals: actual.data.goals, conflicts: actual.data.conflicts, results: actual.data.results, newInformation: actual.data.newInformation }, blankRolesRetained: true, generatedReviews: 0 });
});

test('AT-F05 緊張度2/8/未入力の元三場面へ構成雛形を別案で適用し、算出母数と空欄を保ち正本を採点しない', async ({ page }, info) => {
  const p = createProject('AT-F05 作者値の構成雛形');
  const chapter = createEntity(p.projectId, 'chapter', '構成を試す章');
  const two = createEntity(p.projectId, 'scene', '緊張度2の場面', { chapterId: chapter.id, body: textToRichText('作者が付けた低い緊張度。'), tension: 2 });
  const eight = createEntity(p.projectId, 'scene', '緊張度8の場面', { chapterId: chapter.id, body: textToRichText('作者が付けた高い緊張度。'), tension: 8 });
  const missing = createEntity(p.projectId, 'scene', '緊張度未入力の場面', { chapterId: chapter.id, body: textToRichText('緊張度をまだ決めていない。'), tension: null });
  chapter.data.sceneIds = [two.id, eight.id, missing.id];
  p.entities.push(chapter, two, eight, missing);
  const bytes = await exportScenario(p);
  await attachGiven(info, 'AT-F05', bytes, { chapterId: chapter.id, canonicalOrder: chapter.data.sceneIds, tensionValues: [2, 8, null], structureTemplate: { id: 'three-part', beats: ['導入', '展開', '結末'] } });
  await seed(page, bytes); await writing(page, '作者別案');
  await page.getByLabel('新しい別案の名前', { exact: true }).fill('三場面の構成を逆に試す案');
  await page.getByRole('button', { name: '分岐して別案を作る', exact: true }).click();
  const alternativeId = await page.getByLabel('編集する作者別案', { exact: true }).inputValue();
  expect(alternativeId).toBeTruthy();
  const structure = page.getByRole('region', { name: '構成雛形と盛り上がり', exact: true });
  await structure.getByLabel('構成を試す章', { exact: true }).selectOption(chapter.id);
  await structure.getByLabel('構成雛形', { exact: true }).selectOption('three-part');
  for (const [beat, id] of [['導入', missing.id], ['展開', eight.id], ['結末', two.id]] as const) await structure.getByLabel(`${beat}に置く場面`, { exact: true }).selectOption(id);
  await expect(structure).toContainText('緊張度 2/3件を集計。未入力 1件は空欄のまま');
  await expect(structure.locator('.tension-values')).toContainText('緊張度 2');
  await expect(structure.locator('.tension-values')).toContainText('緊張度 8');
  await expect(structure.locator('.tension-values')).toContainText('緊張度 未入力');
  const beforePreview = await authorFingerprint(page);
  await structure.getByRole('button', { name: '順序の差分を確認', exact: true }).click();
  const preview = structure.getByRole('region', { name: '構成順の差分', exact: true });
  await expect(preview).toContainText('変更前：緊張度2の場面 → 緊張度8の場面 → 緊張度未入力の場面');
  await expect(preview).toContainText('変更後：緊張度未入力の場面 → 緊張度8の場面 → 緊張度2の場面');
  expect(await authorFingerprint(page)).toBe(beforePreview);
  await preview.getByRole('button', { name: '取消', exact: true }).click();
  expect(await authorFingerprint(page)).toBe(beforePreview);
  await structure.getByRole('button', { name: '順序の差分を確認', exact: true }).click();
  await preview.getByRole('button', { name: '別案の下書きへ適用', exact: true }).click();
  expect(await authorFingerprint(page)).toBe(beforePreview);
  await expect(structure).toContainText('緊張度 2/3件を集計。未入力 1件は空欄のまま');
  await page.getByRole('button', { name: '別案を新しい版として保存', exact: true }).click();
  await expect(page.getByText('保存済み 2版', { exact: true })).toBeVisible();
  await page.reload();
  const saved = await backup(page);
  expect(saved.project.entities.find(e => e.id === chapter.id)?.data).toEqual(chapter.data);
  for (const scene of [two, eight, missing]) expect(saved.project.entities.find(e => e.id === scene.id)?.data).toEqual(scene.data);
  const alternative = saved.project.authorAlternatives!.find(a => a.id === alternativeId)!;
  expect(alternative.versions).toHaveLength(2);
  const head = alternative.versions.find(v => v.id === alternative.headVersionId)!;
  expect(head.content.entities.find(e => e.id === chapter.id)).toMatchObject({ data: { sceneIds: [missing.id, eight.id, two.id] } });
  expect(head.content.entities.find(e => e.id === missing.id)).toMatchObject({ data: { tension: null } });
  expect(head.structurePlan).toMatchObject({ templateId: 'three-part', chapterId: chapter.id, assignments: { '導入': missing.id, '展開': eight.id, '結末': two.id } });
  await writing(page, '作者別案');
  await page.getByLabel('編集する作者別案', { exact: true }).selectOption(alternativeId);
  await expect(structure).toContainText('緊張度 2/3件を集計。未入力 1件は空欄のまま');
  await attachObservation(info, 'AT-F05-observed', { alternativeId, savedVersionId: head.id, canonicalOrder: chapter.data.sceneIds, alternativeOrder: [missing.id, eight.id, two.id], measuredCount: 2, totalCount: 3, missingCount: 1, valuesRetained: [2, 8, null], previewAndDraftDidNotCommitCanonical: true, revision: saved.project.revision });
});

test('AT-F06 要約・本文・秘密メモを分けた場面をカードから編集し、選択章の横書き・縦書きと実公開HTMLでルビを確認する', async ({ page }, info) => {
  const p = createProject('AT-F06 本文と秘密メモ');
  const chapter = createEntity(p.projectId, 'chapter', '選んだ章');
  const otherChapter = createEntity(p.projectId, 'chapter', '選ばない章');
  const scene = createEntity(p.projectId, 'scene', '門の場面', { chapterId: chapter.id, summary: textToRichText('門が開く'), body: [{ ...textToRichText('門番は去った')[0], ruby: [{ start: 0, end: 2, text: 'もんばん' }] }], authorNotes: textToRichText('秘密の作者メモ: 鳥は黒幕') });
  const otherScene = createEntity(p.projectId, 'scene', '他章の場面', { chapterId: otherChapter.id, body: textToRichText('選ばない章だけにある文章') });
  chapter.data.sceneIds = [scene.id]; otherChapter.data.sceneIds = [otherScene.id];
  p.entities.push(chapter, otherChapter, scene, otherScene);
  p.entities.forEach(e => { e.status = 'confirmed'; });
  const bytes = await exportScenario(p);
  await attachGiven(info, 'AT-F06', bytes, { selectedChapterId: chapter.id, unselectedChapterId: otherChapter.id, sceneId: scene.id, originalBodyBlockId: scene.data.body[0].id, ruby: scene.data.body[0].ruby, authorNotesBlockIds: scene.data.authorNotes.map(b => b.id) });
  await seed(page, bytes); await writing(page, '章・本文');
