});

test('AT-F13 章へ折りたたんだ階層graphに未接続出口・条件エラー・未確認条件を示し、会話から通常再接続した版をcold保存する', async ({ page }, info) => {
  const p = createProject('AT-F13 章・場面・会話の未接続出口');
  const chapter = createEntity(p.projectId, 'chapter', '階層の章');
  const line = createEntity(p.projectId, 'dialogue_line', '会話の台詞');
  const scene = createEntity(p.projectId, 'scene', '階層の場面', { chapterId: chapter.id, dialogueLineIds: [line.id] });
  chapter.data.sceneIds = [scene.id];
  const variable = createEntity(p.projectId, 'variable', '未確認の鍵状態', { key: 'unconfirmed_key', valueType: 'boolean', initial: { type: 'unknown', value: null, reason: '作者がまだ決めていない' } });
  // Both operands are valid safe integers. The saved expression is valid, but
  // evaluating their sum must report an error rather than hide it as unknown.
  const outOfRange = createEntity(p.projectId, 'variable', '範囲を超える算出状態', { key: 'out_of_range', valueType: 'integer', initial: { type: 'integer', value: 0 }, allowed: { min: -2_147_483_647, max: 2_147_483_647 }, derived: { op: 'add', left: { op: 'value', value: { type: 'integer', value: Number.MAX_SAFE_INTEGER } }, right: { op: 'value', value: { type: 'integer', value: 1 } } } });
  const entry = createEntity(p.projectId, 'flow_node', '会話の入口', { nodeType: 'entry', sceneId: scene.id });
  const end = createEntity(p.projectId, 'flow_node', '会話の出口', { nodeType: 'terminal', sceneId: scene.id, terminalReason: '会話が終わる', gate: { op: 'compare', variableId: outOfRange.id, comparator: 'eq', value: { type: 'integer', value: 0 } } });
  const unfinished = createEntity(p.projectId, 'flow_edge', 'まだ結んでいない会話の出口', { fromId: entry.id, toId: { unresolved: { label: '出口未接続', reason: '作者が接続前' } }, condition: { op: 'compare', variableId: variable.id, comparator: 'eq', value: { type: 'boolean', value: true } } });
  const graph = createEntity(p.projectId, 'flow_graph', '会話の階層graph', { nodeIds: [entry.id, end.id], entryIds: [], exitIds: [end.id], edgeIds: [unfinished.id] });
  p.entities.push(chapter, scene, line, variable, outOfRange, entry, end, unfinished, graph);
  const bytes = await exportScenario(p);
  await attachGiven(info, 'AT-F13', bytes, { chapterId: chapter.id, sceneId: scene.id, lineId: line.id, entryId: entry.id, unresolvedEdgeId: unfinished.id, graphId: graph.id, unknownVariableId: variable.id, errorVariableId: outOfRange.id, conditionError: '算術結果が安全な整数の範囲を超えています。' });
  await seed(page, bytes); await navigate(page, /^構成/);
  await page.getByRole('tab', { name: '分岐', exact: true }).click();
  await page.getByRole('button', { name: '章・場面・会話へ掘り下げる', exact: true }).click();
  const hierarchy = page.getByRole('region', { name: '章・場面・会話と分岐の階層図', exact: true });
  const chapterFolder = hierarchy.locator('.flow-hierarchy-level').first().locator(':scope > li').filter({ has: page.getByRole('button', { name: `章 · ${chapter.name}`, exact: true }) });
  await expect(chapterFolder).toContainText('未完成 2');
  await expect(chapterFolder).toContainText('未確認条件 1');
  await expect(chapterFolder).toContainText('エラー 1');
  await expect(hierarchy.getByRole('button', { name: `台詞 · ${line.name}`, exact: true })).toHaveCount(0);
  await hierarchy.getByRole('button', { name: `${chapter.name}を掘り下げる`, exact: true }).click();
  await hierarchy.getByRole('button', { name: `${scene.name}を掘り下げる`, exact: true }).click();
  await expect(hierarchy.getByRole('button', { name: `台詞 · ${line.name}`, exact: true })).toBeVisible();
  await expect(hierarchy.getByRole('button', { name: '算術結果が安全な整数の範囲を超えています。', exact: true }).first()).toBeVisible();
  await expect(hierarchy.getByRole('button', { name: '入口が未宣言です。', exact: true }).first()).toBeVisible();
  await hierarchy.getByRole('button', { name: '接続の出口が未完成です。', exact: true }).first().click();
  const editor = page.locator('.detail-panel');
  await expect(editor.locator('h2')).toHaveText(unfinished.name);
  await editor.getByLabel('行き先未定の下書き', { exact: true }).uncheck();
  await editor.getByLabel('行き先ノード', { exact: true }).selectOption(end.id);
  await editor.locator('.editor-footer').getByRole('button', { name: '保存する', exact: true }).click();
  await expect(editor.locator('.editor-save-state')).toContainText('端末内保存済み');
  await editor.getByRole('button', { name: '詳細を閉じる', exact: true }).click();
  await expect(chapterFolder).toContainText('未完成 1');
  await expect(chapterFolder).toContainText('未確認条件 1');
  await expect(chapterFolder).toContainText('エラー 1');
  await hierarchy.getByRole('button', { name: `${chapter.name}を折りたたむ`, exact: true }).click();
  await expect(hierarchy.getByRole('button', { name: `台詞 · ${line.name}`, exact: true })).toHaveCount(0);
  await expect(chapterFolder).toContainText('未確認条件 1');
  await expect(chapterFolder).toContainText('エラー 1');
  await page.reload();
  const saved = await backup(page);
  expect(saved.project.entities.find(e => e.id === unfinished.id)).toMatchObject({ data: { fromId: entry.id, toId: end.id, condition: unfinished.data.condition } });
  for (const given of [chapter, scene, line, variable, outOfRange, entry, end, graph]) expect(saved.project.entities.find(e => e.id === given.id)?.data).toEqual(given.data);
  await navigate(page, /^構成/); await page.getByRole('tab', { name: '分岐', exact: true }).click();
  await page.getByRole('button', { name: '章・場面・会話へ掘り下げる', exact: true }).click();
  await expect(chapterFolder).toContainText('未完成 1');
  await expect(chapterFolder).toContainText('未確認条件 1');
  await expect(chapterFolder).toContainText('エラー 1');
  await attachObservation(info, 'AT-F13-observed', { chapterId: chapter.id, edgeId: unfinished.id, resolvedExitId: end.id, graphId: graph.id, revision: saved.project.revision, before: { unfinished: 2, unknown: 1, errors: 1 }, after: { unfinished: 1, unknown: 1, errors: 1 }, unresolvedEntryDeclarationRetained: true, foldedAndColdCountsRetained: true });
});

test('AT-F21 L1/L2と実音声・翻訳・外部参照を保ち、話者改名/並替え/編集/複製/分割後の旧新IDを通常保存する', async ({ page }, info) => {
  const p = createProject('AT-F21 台詞IDと制作対応');
  const speaker = createEntity(p.projectId, 'character', '元の話者');
  const l1 = createEntity(p.projectId, 'dialogue_line', 'L1', { speakerId: speaker.id, text: textToRichText('第一台詞。前半と後半。') });
  const l2 = createEntity(p.projectId, 'dialogue_line', 'L2', { speakerId: speaker.id, text: textToRichText('第二台詞はそのまま。') });
  const scene = createEntity(p.projectId, 'scene', 'L1とL2の場面', { dialogueLineIds: [l1.id, l2.id] });
  const wav = await prepareAsset(new Uint8Array(await readFile('tests/fixtures/media/fixture-tone.wav')), '台詞の実音声.wav');
  const { bytes: wavBytes, preview: _preview, ...metadata } = wav;
  const audio1 = createEntity(p.projectId, 'attachment', 'L1の音声', { ...metadata, stage: 'final' });
  const audio2 = createEntity(p.projectId, 'attachment', 'L2の音声', { ...metadata, stage: 'final' });
  p.entities.push(speaker, l1, l2, scene, audio1, audio2);
  const sourceHash1 = await dialogueContentHash(p, l1), sourceHash2 = await dialogueContentHash(p, l2);
  const translation1 = createEntity(p.projectId, 'localization', 'L1の翻訳', { sourceLineId: l1.id, language: 'en', sourceHash: sourceHash1, text: textToRichText('First line, both halves.'), stage: 'reviewed' });
  const translation2 = createEntity(p.projectId, 'localization', 'L2の翻訳', { sourceLineId: l2.id, language: 'en', sourceHash: sourceHash2, text: textToRichText('Second line remains.'), stage: 'reviewed' });
  const recording1 = createEntity(p.projectId, 'recording', 'L1の収録', { sourceLineId: l1.id, language: 'ja', sourceHash: sourceHash1, translationId: translation1.id, attachmentId: audio1.id, stage: 'reviewed' });
  const recording2 = createEntity(p.projectId, 'recording', 'L2の収録', { sourceLineId: l2.id, language: 'ja', sourceHash: sourceHash2, translationId: translation2.id, attachmentId: audio2.id, stage: 'reviewed' });
  const external1 = createEntity(p.projectId, 'note', 'ゲーム側L1対応', { body: textToRichText('ゲームの会話表 row-L1 に対応する。') });
  const external2 = createEntity(p.projectId, 'note', 'ゲーム側L2対応', { body: textToRichText('ゲームの会話表 row-L2 に対応する。') });
  external1.customValues.gameLineReference = { type: 'ref', value: l1.id };
  external2.customValues.gameLineReference = { type: 'ref', value: l2.id };
  p.entities.push(translation1, translation2, recording1, recording2, external1, external2);
  p.entities.forEach(e => { e.status = 'confirmed'; });
  const bytes = await exportScenario(p, { loadAsset: hash => hash === wav.contentHash ? wavBytes : undefined });
  await attachGiven(info, 'AT-F21', bytes, { speakerId: speaker.id, lineIds: [l1.id, l2.id], translationIds: [translation1.id, translation2.id], recordingIds: [recording1.id, recording2.id], audioIds: [audio1.id, audio2.id], sourceHashes: [sourceHash1, sourceHash2], externalReferenceIds: [external1.id, external2.id], wavSha256: wav.contentHash });
  await seed(page, bytes);
  await openEntity(page, 'character', speaker.name);
  await page.locator('#entity-name').fill('改名した同じ話者'); await saveEditor(page);
  await openEntity(page, 'scene', scene.name);
  const editor = page.locator('.detail-panel');
  await editor.getByRole('tab', { name: '詳細', exact: true }).click();
  await editor.locator('[data-field="dialogueLineIds"]').getByRole('button', { name: '2番を前へ移動', exact: true }).click();
  await saveEditor(page);
  const reordered = await backup(page);
  expect(reordered.project.entities.find(e => e.id === scene.id)).toMatchObject({ data: { dialogueLineIds: [l2.id, l1.id] } });
  for (const given of [translation1, translation2, recording1, recording2, external1, external2]) {
    const actual = reordered.project.entities.find(e => e.id === given.id)!;
    expect(actual.data).toEqual(given.data); expect(actual.customValues).toEqual(given.customValues);
  }
  for (const [line, hash] of [[l1, sourceHash1], [l2, sourceHash2]] as const) {
    const actual = reordered.project.entities.find(e => e.id === line.id)!;
    if (actual.kind !== 'dialogue_line') throw new Error('元台詞がありません');
    expect(await dialogueContentHash(reordered.project, actual)).toBe(hash);
    await openEntity(page, 'dialogue_line', line.name);
    await expect(editor).toContainText('改名した同じ話者');
  }
  await openEntity(page, 'dialogue_line', l1.name);
  await editor.getByRole('textbox', { name: '台詞', exact: true }).fill('第一台詞を編集した。後半も保持する。');
  await saveEditor(page);
  const edited = await backup(page);
  const editedL1 = edited.project.entities.find(e => e.id === l1.id);
  if (!editedL1 || editedL1.kind !== 'dialogue_line') throw new Error('編集後の元L1がありません');
  const editedText = '第一台詞を編集した。後半も保持する。';
  expect(editedL1).toMatchObject({ id: l1.id, projectId: p.projectId, name: l1.name, data: { speakerId: speaker.id } });
  expect(editedL1.data.text).toHaveLength(1);
  const editedBlock = editedL1.data.text[0];
  expect(editedBlock.id).toMatch(ID_PATTERN);
  expect(editedL1.data.text).toEqual([{ id: editedBlock.id, kind: 'paragraph', text: editedText }]);
  expect({ ...editedL1.data, text: l1.data.text }).toEqual(l1.data);
  const editCommand = edited.project.history.find(command => command.targetIds.includes(l1.id)
    && command.before.entities.some(entity => entity.id === l1.id && entity.kind === 'dialogue_line' && JSON.stringify(entity.data.text) === JSON.stringify(l1.data.text))
    && command.after.entities.some(entity => entity.id === l1.id && entity.kind === 'dialogue_line' && JSON.stringify(entity.data.text) === JSON.stringify(editedL1.data.text)));
  if (!editCommand) throw new Error('L1の本文変更を保持する保存操作がありません');
  const oldL1 = editCommand.before.entities.find(entity => entity.id === l1.id);
  if (!oldL1 || oldL1.kind !== 'dialogue_line') throw new Error('初期L1の本文を保持する編集前履歴がありません');
  expect(oldL1.data.text).toEqual(l1.data.text);
  expect(edited.project.entities.find(e => e.id === l2.id)?.data).toEqual(l2.data);
  for (const deliverable of [translation1, recording1]) expect(edited.project.entities.find(e => e.id === deliverable.id)).toMatchObject({ data: { sourceLineId: l1.id, sourceHash: sourceHash1, stage: 'needs_review' } });
  for (const deliverable of [translation2, recording2]) expect(edited.project.entities.find(e => e.id === deliverable.id)?.data).toEqual(deliverable.data);

  await openEntity(page, 'dialogue_line', l1.name);
  await lineChange(page, 'copy', '独立した読み上げ案を比較する');
  const copied = await backup(page);
